const refB=v=>{const x=esById(S.esc),[di,bi,mi]=v.split('|'),d=x.dates.find(z=>z.id===di),b=d&&d.blocks.find(z=>z.id===bi);return {x,d,b,mi:mi!==undefined?+mi:null};};
function sentSt(x){return x.st==='criacao'?'rascunho':'aguardando';}
