 theme:v=>{S.theme=v;try{localStorage.setItem('alva-web-theme',v);}catch(e){}document.documentElement.dataset.theme=v;$$('#mePop .seg button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.v===v));},
