 uSusp:()=>{closePops();const u=uById(S.user);confirmDel({title:u.active?'Suspender acesso administrativo?':'Reativar acesso administrativo?',body:'A conta e o acesso ao app permanecem. Esta ação altera somente a função administrativa.',label:u.active?'Suspender':'Reativar',onConfirm:()=>{u.active=!u.active;idRecord(u.n,u.active?'Acesso reativado':'Acesso suspenso','Função administrativa');admRe();}});},
 uDel:()=>{closePops();const u=uById(S.user);confirmDel({title:'Revogar acesso administrativo?',body:'A pessoa continua como membro, com sua conta e acesso ao app. O papel administrativo e os acessos por área serão retirados.',label:'Revogar acesso',onConfirm:()=>{u.revoked=true;u.active=false;for(let i=SCOPES.length-1;i>=0;i--)if(SCOPES[i].who===u.n)SCOPES.splice(i,1);idRecord(u.n,'Acesso revogado','Papel administrativo e acessos por área encerrados; conta e app mantidos');S.idUserTab='history';admRe();}});},
 uReset:()=>{closePops();const u=uById(S.user);idRecord(u.n,'Redefinição de senha enviada','Envio de e-mail simulado');toast('E-mail de redefinição enviado · demonstração');},uResendInvite:()=>{const u=uById(S.user);idRecord(u.n,'Convite reenviado','Validade de 7 dias');toast('Convite reenviado · demonstração');},
 scSet:v=>{const [id,p]=v.split('|'),x=SCOPES.find(z=>z.id===id);if(!x||x.perm===p)return;const old=x.perm;x.perm=p;idRecord(x.who,'Acesso por área alterado',x.area+' · '+old+' → '+p);admRe();},
